import {readFile,writeFile} from 'node:fs/promises';
const root=new URL('../',import.meta.url);
const files=['gsap-config.js','visual-events.js','miri-art.js','scene-art.js','character-acting.js','balloon.js','visual-director.js','controls-motion.js','flightdeck-motion.js'];
const pieces=await Promise.all(files.map(async file=>`// ---- visuals/updraft/${file} ----\n`+(await readFile(new URL('visuals/updraft/'+file,root),'utf8')).replace(/^import .* from '\.\/[^']+';\r?\n/gm,'')));
const vendor=(await readFile(new URL('visuals/updraft/vendor/gsap.min.js',root),'utf8')).replace(/\/\/# sourceMappingURL=.*$/gm,'');
// UMD expects a writable host.window; do not assign the read-only Window.window in strict ESM.
const gsapVendor='(function(){\n'+vendor+'\n}).call({window:globalThis});\n';
await writeFile(new URL('public/updraft-motion.js',root),'// Generated by scripts/build-updraft-visuals.mjs. Edit visuals/updraft/ sources.\n'+gsapVendor+pieces.join('\n'));
const marker='/* UPDRAFT CINEMA — GENERATED VISUAL LAYER */';
const old=await readFile(new URL('public/updraft.css',root),'utf8');
await writeFile(new URL('public/updraft.css',root),old.split(marker)[0].trimEnd()+'\n\n'+marker+'\n'+await readFile(new URL('visuals/updraft/cinema.css',root),'utf8')+'\n/* FLIGHT DECK — 3D controls, hints, scoring and pilot record */\n'+await readFile(new URL('visuals/updraft/flightdeck.css',root),'utf8'));
// Full-source, offline, no-build visual playground. No trivia scaffolding or API calls.
const css=await readFile(new URL('public/updraft.css',root),'utf8');
const boot=`const preview=new SceneDirector(document.querySelector('#game'));preview.sync(null);document.querySelectorAll('[data-preview]').forEach(button=>button.addEventListener('click',()=>{preview.stop();const kind=button.dataset.preview;preview.play({kind:kind==='celebrate'?'landing':kind,snapshot:{...preview.actual,solved:kind==='celebrate'},detail:'preview'});}));`;
await writeFile(new URL('visuals/updraft/updraft-animation-playground.html',root),`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Updraft — Animation code & playground</title><style>${css}</style><body><main id="game"><h1>Up<em>draft.</em></h1><p>A visual playground for Miri Quill. These buttons preview animations; they do not play a separate game or change scores.</p><div class="start-actions">${['correct','wrong','rare','sky','landing','celebrate','wave'].map(kind=>`<button class="secondary" data-preview="${kind}">${kind}</button>`).join('')}</div><p>Open this file in a text editor. The CONFIG object at the top of the module script contains every timing, easing and intensity control. This file includes GSAP and SVG artwork and works offline without a build step.</p></main><script>${gsapVendor}</script><script type="module">${pieces.join('\n')}\n${boot}</script></body></html>`);
console.log('Built isolated Updraft visual layer; no game or server modules bundled.');
